  /* ---------- Probability ---------- */
  ["prob",1,"num","You roll a fair die until a 6 appears. What is the expected number of rolls?",6,"Each roll succeeds with probability 1/6.","Geometric distribution with p = 1/6, so E = 1/p = 6."],
  ["prob",1,"num","You flip two fair coins. Given that at least one landed heads, what is the probability both did?",1/3,"List the outcomes that are still possible.","HH, HT and TH remain equally likely. Only one of the three is HH."],
  ["prob",2,"num","What is the expected number of fair coin flips until you see two heads in a row?",6,"Track two states: no streak, and one head so far.","E0 = 1 + ½E1 + ½E0 and E1 = 1 + ½E0. Solving gives E0 = 6."],
  ["prob",2,"num","What is the expected number of fair coin flips until you see heads immediately followed by tails?",4,"Once you have a head, a tail always finishes the pattern.","Wait for the first head (2 flips on average), then wait for a tail (2 more). Total 4."],
  ["prob",1,"num","Roll two fair dice. What is the probability the sum is 7?",1/6,"Count pairs out of 36.","Six of the 36 equally likely outcomes sum to 7."],
  ["prob",2,"num","Roll two fair dice. What is the expected value of the larger number?",161/36,"Find P(max = k) first.","P(max = k) = (2k − 1)/36. Summing k(2k − 1)/36 over k = 1..6 gives 161/36 ≈ 4.472."],
  ["prob",3,"num","A stick is broken at two independent uniformly random points. What is the probability the three pieces can form a triangle?",1/4,"Every piece must be shorter than half the stick.","The condition 'all pieces under ½' carves out a region with area ¼ of the unit square."],
  ["prob",1,"num","Ten cards are shuffled at random. What is the expected number that end up in their original position?",1,"Use linearity of expectation.","Each card stays put with probability 1/10, and there are 10 cards, so the expectation is 1."],
  ["prob",1,"num","Roll a fair die four times. What is the probability of at least one 6? (Decimal is fine.)",671/1296,"Use the complement.","1 − (5/6)⁴ = 671/1296 ≈ 0.5177."],
  ["prob",1,"num","X and Y are independent Uniform(0,1). What is E[max(X, Y)]?",2/3,"P(max ≤ t) = t².","The density of the max is 2t, so E = ∫ 2t² dt = 2/3. In general n/(n+1)."],
  ["prob",2,"num","What is the expected number of die rolls needed to see all six faces at least once?",14.7,"Think of each new face as its own waiting time.","6/6 + 6/5 + 6/4 + 6/3 + 6/2 + 6/1 = 14.7."],
  ["prob",1,"num","You draw 2 cards from a standard 52-card deck. What is the probability both are aces?",1/221,"Multiply the two draws.","(4/52) × (3/51) = 1/221."],
  ["prob",1,"num","Three independent Uniform(0,1) draws. What is the expected value of the smallest?",1/4,"There is a neat formula for n uniforms.","E[min of n uniforms] = 1/(n+1) = 1/4."],
  ["prob",2,"num","You roll a die and are paid its face value in dollars. You may reroll once, but must keep the second roll. What is your expected payoff with optimal play?",4.25,"Reroll only when the current roll is below what a fresh roll is worth.","A fresh roll is worth 3.5, so keep 4, 5 or 6 (average 5) and reroll 1–3. ½ × 5 + ½ × 3.5 = 4.25."],
  ["prob",1,"num","A bag holds 3 red and 2 blue balls. Draw 2 without replacement. What is the probability they are the same color?",2/5,"Count same-color pairs.","(C(3,2) + C(2,2)) / C(5,2) = 4/10."],
  ["prob",2,"num","A symmetric random walk starts at 0. What is the probability it reaches +2 before −1?",1/3,"The walk is a martingale.","Optional stopping: 2p − (1 − p) = 0, so p = 1/3."],
  ["prob",2,"num","You have $3 and bet $1 on fair coin flips until you have $10 or nothing. What is the probability you reach $10?",0.3,"Fair game: your expected wealth never changes.","10p = 3, so p = 3/10."],
  ["prob",1,"num","Flip 10 fair coins. Given the first is heads, what is the expected number of heads?",5.5,"The first coin is fixed.","1 + 9 × ½ = 5.5."],
  ["prob",2,"num","In a room of 23 people with birthdays uniform over 365 days, what is the probability at least two share a birthday? (Decimal.)",0.5073,"Compute the chance that all are different.","1 − (365 × 364 × … × 343)/365²³ ≈ 0.507."],
  ["prob",1,"num","Roll three fair dice. What is the probability all three show different numbers?",5/9,"Count ordered outcomes.","6 × 5 × 4 / 216 = 120/216 = 5/9."],
  ["prob",1,"num","Roll two fair dice. What is the probability at least one shows a 6?",11/36,"Complement again.","1 − (5/6)² = 11/36."],
  ["prob",1,"num","Two independent fair dice. What is the expected value of their product?",12.25,"Independence lets expectations multiply.","E[XY] = E[X]E[Y] = 3.5 × 3.5 = 12.25."],
  ["prob",2,"num","Roll one fair die. What is the expected value of the square of the result?",91/6,"Average 1, 4, 9, 16, 25, 36.","(1 + 4 + 9 + 16 + 25 + 36)/6 = 91/6 ≈ 15.17."],
  ["prob",1,"num","Flip a fair coin until tails. You get $1 for every head before the first tail. What is your expected payout?",1,"The number of heads is geometric starting at 0.","E = (1 − p)/p with p = ½, which is 1."],
  ["prob",1,"num","Three doors, one prize. You pick a door, the host opens a different empty door and offers a switch. What is your probability of winning if you switch?",2/3,"Your first pick is right only a third of the time.","Switching wins whenever the first pick was wrong, which happens with probability 2/3."],
  ["prob",1,"num","A family has two children and the older one is a girl. What is the probability both are girls?",1/2,"Knowing which child is a girl matters.","Only the younger child is unknown, so the probability is ½."],
  ["prob",2,"num","Three cards: one red on both sides, one white on both sides, one red on one side and white on the other. You draw one at random and see a red side. What is the probability the other side is red?",2/3,"Count red faces, not cards.","There are three red faces you could be seeing, and two of them belong to the red-red card."],
  ["prob",2,"num","A disease affects 1% of people. A test catches 99% of cases and falsely flags 1% of healthy people. You test positive. What is the probability you are sick?",0.5,"Compare true positives to false positives.","True positives: 0.01 × 0.99. False positives: 0.99 × 0.01. They are equal, so the answer is ½."],
  ["prob",2,"num","You roll a die until you get the same number twice in a row. What is the expected number of rolls?",7,"After the first roll, each roll matches the previous with probability 1/6.","1 roll to start, then a geometric wait with p = 1/6: 1 + 6 = 7."],
  ["prob",3,"num","What is the probability a random 5-card poker hand is a flush, counting straight flushes? (Decimal.)",4*1287/2598960,"Choose a suit, then 5 of its 13 cards.","4 × C(13,5) / C(52,5) = 5148/2598960 ≈ 0.00198."],
  ["prob",1,"num","Draw two cards from a shuffled deck. What is the probability they share a suit?",4/17,"The first card can be anything.","12 of the remaining 51 cards match its suit: 12/51 = 4/17."],
  ["prob",2,"num","Pick a uniform point in the unit square. What is the probability it lies within distance ½ of the center?",Math.PI/4,"That region is a circle.","A circle of radius ½ has area π/4, all inside the square."],
  ["prob",2,"num","X and Y are independent Uniform(0,1). What is E|X − Y|?",1/3,"Integrate over the square, or use symmetry.","E|X − Y| = 2∫∫_{x>y}(x − y) = 1/3."],
  ["prob",2,"num","A stick of length 1 is broken at a uniform point. What is the expected length of the longer piece?",3/4,"The longer piece is uniform on [½, 1].","Its average is (½ + 1)/2 = 3/4."],
  ["prob",1,"num","What is the variance of the number of heads in 100 fair coin flips?",25,"Binomial variance is np(1 − p).","100 × ½ × ½ = 25."],
  ["prob",2,"num","What is the standard deviation of the sum of two fair dice? (Decimal.)",Math.sqrt(35/6),"Variance of one die is 35/12.","Var = 2 × 35/12 = 35/6, so SD ≈ 2.415."],
  ["prob",3,"num","n people throw hats in a pile and each grabs one at random. As n grows large, what is the probability nobody gets their own hat? (Decimal.)",1/Math.E,"Inclusion–exclusion gives a famous series.","The derangement probability tends to Σ(−1)ᵏ/k! = 1/e ≈ 0.3679."],
  ["prob",2,"num","Roll a fair die 6 times. What is the expected number of distinct faces you see? (Decimal.)",6*(1-Math.pow(5/6,6)),"Linearity: ask for each face whether it appears.","Each face appears with probability 1 − (5/6)⁶, so E = 6(1 − (5/6)⁶) ≈ 3.99."],
  ["prob",1,"num","Roll two fair dice. What is the probability their product is even?",3/4,"A product is odd only if both are odd.","1 − (½)² = 3/4."],
  ["prob",2,"num","Events arrive as a Poisson process with rate 2 per minute. What is the probability of no events in a given minute? (Decimal.)",Math.exp(-2),"P(N = 0) for Poisson(λ).","e^(−2) ≈ 0.1353."],
  ["prob",1,"num","Z is standard normal. What is P(Z > 1.96), to three decimals?",0.025,"It's the classic two-sided 95% cutoff.","1.96 leaves 2.5% in each tail."],
  ["prob",2,"num","X and Y are independent Exponential(1). What is E[max(X, Y)]?",1.5,"The min arrives first, then memorylessness.","E[min] = ½, then the other waits another 1 on average: ½ + 1 = 1.5."],
  ["prob",1,"num","X and Y are independent Exponential(1). What is E[min(X, Y)]?",0.5,"The min of exponentials is exponential.","min ~ Exponential(2), whose mean is ½."],
  ["prob",2,"num","A symmetric random walk starts at 0. What is the expected number of steps until it first hits +3 or −3?",9,"For barriers at −a and +b the answer is ab.","E[T] = a × b = 3 × 3 = 9."],
  ["prob",3,"num","An ant walks randomly along the edges of a cube, choosing each of 3 edges equally at each vertex. What is the expected number of moves to reach the opposite corner?",10,"Group vertices by distance from the target (3, 2, 1, 0).","Solving E3 = 1 + E2, E2 = 1 + ⅓E3 + ⅔E1, E1 = 1 + ⅔E2 gives E3 = 10."],
  ["prob",3,"num","A coin's heads probability p is uniform on [0,1]. You flip it once and see heads. What is the probability the next flip is heads?",2/3,"Update the prior with one observation.","The posterior is Beta(2,1) with mean 2/3 (Laplace's rule of succession)."],
  ["prob",1,"num","Flip 3 fair coins. What is the probability of exactly 2 heads?",3/8,"Count arrangements.","C(3,2)/8 = 3/8."],
  ["prob",3,"num","You turn cards from a shuffled deck until the first ace appears. What is the expected number of cards turned, including the ace?",10.6,"The 4 aces split the 48 other cards into 5 gaps of equal expected size.","Each gap averages 48/5 = 9.6 cards, plus the ace: 10.6."],
  ["prob",2,"num","Two players take turns flipping a fair coin. The first to flip heads wins. What is the probability the first player wins?",2/3,"Condition on the first two flips.","p = ½ + ¼p, so p = 2/3."],
  ["prob",3,"num","You roll a die until a 6 appears and add up every roll, including the 6. What is the expected total?",21,"Rolls before the 6 are uniform on 1–5.","On average 5 rolls come before the 6, each averaging 3, so 15 + 6 = 21."],
  ["prob",3,"num","Three points are chosen uniformly on a circle. What is the probability the triangle they form contains the center?",1/4,"The triangle misses the center when all three fit in a semicircle.","P(all in a semicircle) = 3/4, so the answer is 1/4."],
  ["prob",1,"num","You roll two dice repeatedly. What is the expected number of rolls until the sum is 7?",6,"Each roll succeeds with probability 1/6.","Geometric with p = 1/6, so 6 rolls."],
  ["prob",1,"num","Roll two fair dice. What is the probability the sum is at least 10?",1/6,"List sums of 10, 11 and 12.","3 + 2 + 1 = 6 outcomes out of 36."],
  ["prob",2,"num","A fair coin is flipped 4 times. What is the probability of getting at least 3 heads in a row?",3/16,"List the sequences.","HHHH, HHHT and THHH: 3 of 16."],
  ["prob",2,"num","You pick 2 numbers without replacement from 1 to 10. What is the probability their sum is even?",4/9,"Both odd or both even.","(C(5,2) + C(5,2)) / C(10,2) = 20/45 = 4/9."],
  ["prob",3,"num","A fair coin is flipped 6 times. What is the probability of exactly 3 heads?",5/16,"C(6,3) over 2⁶.","20/64 = 5/16."],

  ["prob",3,"num","What is the expected number of fair coin flips until you see heads, tails, heads (HTH)?",10,"After HT, a tail sends you all the way back, but a head finishes.","States: start, H, HT. Solving the linear equations gives 10. (Compare HHT, which takes 8.)"],
  ["prob",3,"num","What is the expected number of fair coin flips until three heads in a row?",14,"For k heads in a row the answer is 2^(k+1) − 2.","2⁴ − 2 = 14."],
  ["prob",2,"num","You turn cards from a shuffled deck. What is the probability the first ace appears before the first king?",1/2,"Only aces and kings matter.","Among the 8 aces and kings, the first is equally likely to be either type: ½."],
  ["prob",3,"num","A point is chosen uniformly in the unit disk. What is its expected distance from the center?",2/3,"The density of the radius is 2r.","E[R] = ∫₀¹ r · 2r dr = 2/3."],
  ["prob",1,"num","A random integer from 1 to 100 is chosen. What is the probability it is divisible by 3 or 5?",0.47,"Inclusion–exclusion.","33 + 20 − 6 = 47 numbers, so 0.47."],

  /* ---------- Brainteasers ---------- */
  ["brain",1,"num","A bat and ball cost $1.10 together. The bat costs $1.00 more than the ball. How many cents is the ball?",5,"Don't trust your first instinct.","Ball = x, bat = x + 1. 2x + 1 = 1.10, so x = 0.05."],
  ["brain",2,"num","How many trailing zeros does 100! have?",24,"Count factors of 5.","⌊100/5⌋ + ⌊100/25⌋ = 20 + 4 = 24."],
  ["brain",2,"num","What is the angle in degrees between the hour and minute hands at 3:15?",7.5,"The hour hand keeps moving.","Minute hand at 90°. Hour hand at 90° + 15 × 0.5° = 97.5°. Difference 7.5°."],
  ["brain",1,"num","Ten people each shake hands once with every other person. How many handshakes happen?",45,"Choose pairs.","C(10,2) = 45."],
  ["brain",3,"num","25 horses, a track that races 5 at a time, no stopwatch. What is the fewest races needed to find the 3 fastest?",7,"Run 5 heats, then race the winners.","5 heats + 1 race of winners + 1 race of the 5 remaining contenders = 7."],
  ["brain",2,"num","100 closed lockers. Student k toggles every k-th locker, for k = 1..100. How many lockers are open at the end?",10,"A locker is toggled once per divisor.","Only perfect squares have an odd number of divisors: 1, 4, …, 100 → 10 lockers."],
  ["brain",1,"num","What is 1 + 2 + 3 + … + 100?",5050,"Pair the ends.","50 pairs that each sum to 101: 5050."],
  ["brain",3,"num","12 coins, one is fake and is either heavier or lighter. With a balance scale, what is the minimum number of weighings that always finds it and whether it's heavy or light?",3,"Each weighing has three outcomes.","24 possibilities, and 3³ = 27 ≥ 24, achievable with a careful scheme: 3."],
  ["brain",1,"num","How many distinct arrangements are there of the letters in LEVEL?",30,"Divide out repeated letters.","5! / (2! × 2!) = 30."],
  ["brain",2,"num","How many rectangles of any size are on an 8×8 chessboard?",1296,"A rectangle is two horizontal and two vertical lines.","C(9,2)² = 36² = 1296."],
  ["brain",2,"num","Two trains 100 miles apart head toward each other at 50 mph each. A bird flies back and forth between them at 75 mph until they meet. How many miles does the bird fly?",75,"Don't sum the zig-zags.","The trains meet in 1 hour, so the bird flies 75 miles."],
  ["brain",2,"num","How many times do the hour and minute hands overlap in 12 hours?",11,"The minute hand laps the hour hand.","The minute hand gains a full lap 11 times every 12 hours."],
  ["brain",2,"num","What is the last digit of 7^2026?",9,"Powers of 7 cycle their last digit.","Last digits cycle 7, 9, 3, 1. 2026 leaves remainder 2 mod 4, so the digit is 9."],
  ["brain",1,"num","How many diagonals does a 10-sided polygon have?",35,"Each vertex connects to n − 3 others.","10 × 7 / 2 = 35."],
  ["brain",1,"num","What is 15% of 15% of 2000?",45,"Multiply the percentages first.","0.15 × 0.15 = 0.0225, and 0.0225 × 2000 = 45."],
  ["brain",2,"num","What is the sum of the digits of all integers from 1 to 99?",900,"Each digit appears equally often in each place.","Units: 10 × 45. Tens: 10 × 45. Total 900."],
  ["brain",2,"num","A snail climbs 3 feet each day and slips 2 feet each night. How many days to escape a 10-foot well?",8,"On the final day it doesn't slip.","After 7 days it is at 7 feet; on day 8 it climbs to 10 and escapes."],
  ["brain",3,"num","100 prisoners line up wearing red or blue hats, each seeing everyone ahead. From the back, each calls a color. With the best agreed strategy, how many are guaranteed to survive?",99,"The first speaker can encode parity.","The last in line announces the parity of red hats ahead; everyone else can deduce their own. Guaranteed 99."],
  ["brain",2,"num","How many ways can you climb 10 stairs taking 1 or 2 steps at a time?",89,"This follows a famous recurrence.","f(n) = f(n−1) + f(n−2): Fibonacci, f(10) = 89."],
  ["brain",2,"num","What is the smallest positive integer divisible by every number from 1 to 10?",2520,"Take the highest prime powers.","2³ × 3² × 5 × 7 = 2520."],

  /* ---------- Options ---------- */
  ["options",1,"mc","Roughly what is the delta of an at-the-money call with a short time to expiry?",["0.25","0.5","0.75","1.0"],1,"Think of the chance it finishes in the money.","Near the money the option is close to a coin flip, so delta ≈ 0.5."],
  ["options",1,"mc","Which is put–call parity for European options on a non-dividend stock?",["C + P = S + K","C − P = S − Ke^(−rT)","C − P = K − S","C = P"],1,"Build a forward from options.","Long call plus short put pays S_T − K at expiry, the same as a forward."],
  ["options",2,"mc","Which Greek spikes for an at-the-money option close to expiry?",["Rho","Vega","Gamma","Theta of a deep ITM option"],2,"Delta changes fastest where?","Delta jumps from 0 to 1 across a narrow price range, so gamma is huge."],
  ["options",1,"mc","Buying a straddle (call + put, same strike) is mainly a bet that…",["the price rises","the price falls","the price moves a lot either way","rates rise"],2,"It pays in both directions.","A straddle profits from large moves, so it is long volatility."],
  ["options",2,"mc","If implied volatility doubles, an at-the-money option's price roughly…",["stays the same","doubles","quadruples","halves"],1,"There's a linear approximation for ATM prices.","ATM price ≈ 0.4 · S · σ · √T, linear in σ."],
  ["options",1,"mc","The theta of a long vanilla option is usually…",["positive","negative","zero","equal to gamma"],1,"What happens as time passes?","Time decay erodes value, so theta is negative for the holder."],
  ["options",2,"mc","Vega is largest for which option?",["Deep ITM, short-dated","ATM, long-dated","Deep OTM, short-dated","All are equal"],1,"Vega grows with √T and peaks near the money.","Vega ∝ S·φ(d₁)·√T, largest for ATM long-dated options."],
  ["options",1,"mc","A deep in-the-money call has a delta close to…",["0","0.5","1","−1"],2,"It behaves like stock.","It will almost surely be exercised, so it moves one-for-one with the stock."],
  ["options",2,"mc","Long a call and short a put at the same strike and expiry is equivalent to…",["a straddle","a synthetic long forward","a covered call","a butterfly"],1,"Check the payoff at expiry.","Payoff S_T − K in every state, which is a long forward."],
  ["options",3,"mc","For an American call on a stock that pays no dividends, early exercise is…",["often optimal","never optimal","optimal at the money","optimal near expiry only"],1,"Compare exercising with selling the option.","The call is always worth more alive than its intrinsic value, so you never exercise early."],
  ["options",2,"mc","Holding everything else fixed, higher interest rates make a call…",["cheaper","more expensive","unchanged","worthless"],1,"The strike is paid in the future.","A higher rate lowers the present value of the strike, raising the call price (positive rho)."],
  ["options",2,"mc","On equity indices, implied volatility is typically higher for…",["high strikes","low strikes","the ATM strike","all strikes equally"],1,"Investors pay up for crash protection.","The equity skew: downside puts trade at higher implied vol."],
  ["options",1,"mc","A put's delta lies in which range?",["0 to 1","−1 to 0","−0.5 to 0.5","1 to 2"],1,"Puts gain when the stock falls.","Put delta = call delta − 1, so it lies between −1 and 0."],
  ["options",2,"mc","Long stock plus a short call has the same payoff shape as…",["a long put","a short put","a long call","a straddle"],1,"Draw the payoff.","A covered call caps the upside and keeps the downside, like a short put."],
  ["options",3,"mc","A quick estimate of an ATM straddle's price is…",["0.4 · S · σ · √T","0.8 · S · σ · √T","S · σ · T","σ / √T"],1,"It's two ATM options.","Each ATM option ≈ 0.4 · S · σ · √T, so the straddle ≈ 0.8 · S · σ · √T."],

  ["options",1,"mc","The gamma of a long option position (call or put) is…",["positive","negative","zero","positive for calls, negative for puts"],0,"Option payoffs are convex.","Long options are long convexity, so gamma is positive for both calls and puts."],
  ["options",1,"mc","A call spread (long a K₁ call, short a K₂ call, K₁ < K₂) has a maximum payoff of…",["unlimited","K₂ − K₁","the premium paid","zero"],1,"The short call caps the upside.","Above K₂ the payoff is flat at K₂ − K₁."],
  ["options",2,"mc","Selling an option and delta-hedging it is mainly a bet that realized volatility will be…",["higher than implied","lower than implied","zero","equal to interest rates"],1,"The hedger pays gamma costs as the stock moves.","Short gamma loses when the stock moves more than implied vol priced in."],
  ["options",3,"mc","In Black–Scholes, the price of a cash-or-nothing digital call paying $1 is…",["e^(−rT) · N(d₂)","N(d₁)","S · N(d₁)","Always 0.5"],0,"N(d₂) is a risk-neutral probability.","It pays $1 when S_T > K, which has risk-neutral probability N(d₂), discounted."],
  ["options",1,"mc","The delta of an at-the-money straddle is approximately…",["0","0.5","1","−1"],0,"Add the call and put deltas.","≈ 0.5 + (−0.5) = 0."],
  ["options",1,"mc","Which position has unlimited potential loss?",["Long call","Long put","Short call","Short put"],2,"Which way can a stock go without limit?","A short call loses more the higher the stock rises, with no cap."],
  ["options",2,"mc","A long call butterfly (long K₁, short 2 × K₂, long K₃, evenly spaced) pays the most when the stock finishes…",["at K₁","at K₂","above K₃","below K₁"],1,"Draw the tent-shaped payoff.","The payoff peaks at the middle strike, K₂."],
  ["options",1,"mc","As expiry approaches, the time value of an out-of-the-money option…",["grows","goes to zero","stays constant","doubles"],1,"At expiry only intrinsic value is left.","An OTM option has no intrinsic value, so it decays to zero."],
  ["options",1,"mc","Implied volatility is…",["the historical standard deviation of returns","the volatility that makes the model price equal the market price","the VIX index","the strike divided by spot"],1,"It's backed out of a price.","Invert the pricing model on the market price to get implied vol."],
  ["options",2,"mc","A stock goes ex-dividend tomorrow with a large dividend. Compared with no dividend, a call on it today is…",["cheaper","more expensive","the same","worthless"],0,"The stock drops by the dividend.","The expected forward price falls, so the call is worth less."],

  /* ---------- Statistics ---------- */
  ["stats",1,"mc","For a constant a, Var(aX) equals…",["a · Var X","a² · Var X","Var X","|a| · Var X"],1,"Variance is in squared units.","Var(aX) = a² Var X."],
  ["stats",1,"mc","The correlation between two random variables always lies between…",["0 and 1","−1 and 1","−∞ and ∞","0 and ∞"],1,"Think Cauchy–Schwarz.","|Corr| ≤ 1 by the Cauchy–Schwarz inequality."],
  ["stats",1,"mc","The central limit theorem says the mean of many iid draws with finite variance is approximately…",["uniform","normal","exponential","Poisson"],1,"Sums of many small effects.","Standardized sample means converge to a normal distribution."],
  ["stats",2,"mc","What is the variance of a Uniform(0,1) random variable?",["1/2","1/3","1/12","1/4"],2,"E[X²] − E[X]².","1/3 − 1/4 = 1/12."],
  ["stats",1,"mc","A Poisson(λ) random variable has variance…",["λ","λ²","√λ","1/λ"],0,"Mean and variance coincide.","For a Poisson distribution, mean = variance = λ."],
  ["stats",1,"mc","Increasing a sample from 100 to 400 observations cuts the standard error of the mean by a factor of…",["4","2","16","√2"],1,"SE ∝ 1/√n.","√(400/100) = 2."],
  ["stats",2,"mc","Adding another variable to an OLS regression never decreases…",["adjusted R²","in-sample R²","out-of-sample accuracy","the p-values"],1,"More freedom can't fit worse in-sample.","In-sample R² can only rise or stay the same; adjusted R² can fall."],
  ["stats",2,"mc","Two assets have correlation −1. You can combine them into a portfolio with variance…",["zero","their average","their sum","it depends on the mean"],0,"Perfect negative correlation hedges completely.","Weights inversely proportional to their volatilities give zero variance."],
  ["stats",1,"mc","Bayes' rule: P(A | B) equals…",["P(B | A) P(A) / P(B)","P(A) P(B)","P(B | A)","P(A) / P(B)"],0,"Write P(A and B) two ways.","P(A|B)P(B) = P(B|A)P(A)."],
  ["stats",2,"mc","A 95% confidence interval means…",["there's a 95% chance the true value is in this interval","95% of intervals built this way would contain the true value","95% of the data lie inside it","the p-value is 0.95"],1,"The randomness is in the interval, not the parameter.","It's a statement about the procedure's long-run coverage."],
  ["stats",1,"mc","A Type I error is…",["rejecting a true null hypothesis","failing to reject a false null","a coding bug","a biased sample"],0,"A false alarm.","Type I is a false positive; Type II is a miss."],
  ["stats",1,"mc","The expected value of a Binomial(n, p) random variable is…",["np","np(1 − p)","n/p","p/n"],0,"Sum of n Bernoulli(p).","Linearity: n × p."],
  ["stats",1,"mc","X is standard normal. What is the correlation between X and X²?",["1","0","−1","0.5"],1,"Compute Cov(X, X²).","Cov = E[X³] = 0 by symmetry, even though they are dependent."],
  ["stats",1,"mc","To annualize a Sharpe ratio computed from daily returns, multiply by…",["252","√252","1/252","12"],1,"Mean scales with T, volatility with √T.","Sharpe scales with √T, so multiply by √252."],
  ["stats",1,"mc","For independent X and Y, Var(X + Y) equals…",["Var X + Var Y","Var X − Var Y","(Var X)(Var Y)","2 Cov(X,Y)"],0,"The covariance term vanishes.","Var(X + Y) = Var X + Var Y + 2Cov, and Cov = 0."],
  ["stats",1,"mc","The standard error of a sample mean of n independent draws with SD σ is…",["σ","σ/n","σ/√n","σ√n"],2,"Averaging cuts variance by n.","Var(mean) = σ²/n, so SE = σ/√n."],
  ["stats",2,"mc","Correlation stays the same under which change to X?",["Squaring it","Multiplying by a positive constant and adding a constant","Taking logs","Multiplying by −1"],1,"Correlation is scale-free.","Positive affine maps leave correlation unchanged; −1 flips its sign."],
  ["stats",2,"mc","A p-value is the probability of…",["the null being true","data at least this extreme if the null is true","the alternative being true","making an error"],1,"It's conditional on the null.","It measures how surprising the data would be if the null hypothesis held."],
  ["stats",2,"mc","E[E[X | Y]] equals…",["E[Y]","E[X]","Var X","0"],1,"The law of total expectation.","Averaging the conditional mean over Y recovers E[X]."],
  ["stats",1,"mc","X and Y are independent N(0,1). X + Y is distributed as…",["N(0,1)","N(0,2)","N(0,4)","N(0,√2)"],1,"Variances add.","Normal with mean 0 and variance 2."],
  ["stats",2,"mc","The OLS slope when regressing y on x is…",["Cov(x,y)/Var(y)","Cov(x,y)/Var(x)","Corr(x,y)","Var(x)/Cov(x,y)"],1,"Minimize squared error.","β = Cov(x,y)/Var(x)."],
  ["stats",1,"mc","A strategy looks great in backtest but fails live. The most likely cause is…",["too little data","overfitting","low volatility","rounding"],1,"Many parameters, one history.","Fitting noise in-sample is overfitting; out-of-sample performance exposes it."],
  ["stats",2,"mc","Which returns add up over time?",["Simple returns","Log returns","Excess returns","Percentage returns"],1,"log(a·b) = log a + log b.","Log returns over consecutive periods sum to the total log return."],
  ["stats",3,"mc","What is the median of an Exponential(1) random variable?",["1","ln 2","½","e"],1,"Solve 1 − e^(−m) = ½.","m = ln 2 ≈ 0.693."],

  /* ---------- Code ---------- */
  ["code",1,"mc","Python: print(0.1 + 0.2 == 0.3)",["True","False","Error","None"],1,"Floating point.","0.1 + 0.2 is 0.30000000000000004 in binary floating point."],
  ["code",1,"mc","Python: a = [1, 2, 3]; b = a; b.append(4); print(len(a))",["3","4","Error","7"],1,"Assignment doesn't copy.","b and a name the same list object."],
  ["code",2,"mc","What does pushing onto a binary heap of n items cost?",["O(1)","O(log n)","O(n)","O(n log n)"],1,"The item sifts up.","At most the tree's height, O(log n)."],
  ["code",2,"mc","NumPy: np.std(x) uses which denominator by default?",["n","n − 1","n + 1","√n"],0,"Check the ddof default.","ddof = 0 by default; pass ddof=1 for the sample SD."],
  ["code",1,"mc","Python: print([i * i for i in range(4)])",["[1, 4, 9, 16]","[0, 1, 4, 9]","[0, 1, 2, 3]","Error"],1,"range starts at 0.","range(4) is 0, 1, 2, 3."],
  ["code",1,"mc","Average cost of looking up a key in a Python dict?",["O(1)","O(log n)","O(n)","O(n²)"],0,"It's a hash table.","Hash lookups are O(1) on average."],
  ["code",1,"mc","Binary search on a sorted array of n items costs…",["O(1)","O(log n)","O(n)","O(n log n)"],1,"Halve each step.","The range halves every comparison."],
  ["code",1,"mc","Python: print(7 // 2)",["3.5","3","4","Error"],1,"Floor division.","7 // 2 floors 3.5 down to 3."],
  ["code",2,"mc","Python: print(-7 // 2)",["-3","-4","-3.5","3"],1,"Floor goes toward negative infinity.","−3.5 floors to −4."],
  ["code",2,"mc","The best possible worst-case cost of a comparison sort is…",["O(n)","O(n log n)","O(log n)","O(n²)"],1,"Count the possible orderings.","Distinguishing n! orderings needs about log₂(n!) ≈ n log n comparisons."],
  ["code",3,"mc","Python: def f(x=[]): x.append(1); return len(x) — after calling f() once, what does print(f()) show?",["1","2","0","Error"],1,"Default arguments are created once.","The same list is reused between calls, so the second call sees length 2."],
  ["code",1,"mc","Python: print('abc'[::-1])",["abc","cba","a","Error"],1,"Negative step.","A step of −1 reverses the string."],
  ["code",2,"mc","Python: print(len(set([1, 1, 2, 3, 3, 3])))",["6","3","2","1"],1,"Sets drop duplicates.","The set is {1, 2, 3}."],
  ["code",1,"mc","Python 3: print(type(3 / 2).__name__)",["int","float","Fraction","Error"],1,"/ is true division.","3 / 2 is 1.5, a float."],
  ["code",1,"mc","Python: print(bool([]))",["True","False","None","Error"],1,"Empty containers are falsy.","An empty list evaluates to False."],
  ["code",2,"mc","Python: x = (1); print(type(x).__name__)",["tuple","int","list","Error"],1,"Parentheses alone don't make a tuple.","You need a trailing comma: (1,) is a tuple."],
  ["code",2,"mc","Inserting at the front of a Python list of n items costs…",["O(1)","O(log n)","O(n)","O(n²)"],2,"Everything shifts.","All n elements move one slot, so O(n). Use collections.deque for O(1)."],
  ["code",1,"mc","Python: print(sorted([3, 1, 2], reverse=True))",["[1, 2, 3]","[3, 2, 1]","[3, 1, 2]","None"],1,"reverse=True sorts descending.","Descending order: [3, 2, 1]."],
  ["code",3,"mc","Python 3: print(round(2.5))",["2","3","2.5","Error"],0,"Python rounds halves to even.","Banker's rounding: 2.5 rounds to 2, 3.5 rounds to 4."],
  ["code",1,"mc","Python: print('a' * 3)",["a3","aaa","Error","['a', 'a', 'a']"],1,"Strings repeat with *.","'a' * 3 is 'aaa'."],
  ["code",3,"mc","Python: a = [[0] * 2] * 2; a[0][0] = 1; print(a)",["[[1, 0], [0, 0]]","[[1, 0], [1, 0]]","[[1, 1], [0, 0]]","Error"],1,"The outer * copies references.","Both rows are the same list object, so both change."],
  ["code",1,"mc","Python: print(10 % 3)",["3","1","0","3.33"],1,"Remainder.","10 = 3 × 3 + 1."],
  ["code",1,"mc","Python: print(len('hello world'.split()))",["1","2","11","10"],1,"split() breaks on whitespace.","['hello', 'world'] has 2 items."],
  ["code",2,"mc","Memory needed to store a dense n × n matrix is…",["O(n)","O(n log n)","O(n²)","O(2ⁿ)"],2,"Count the entries.","There are n² entries."],
  ["code",2,"mc","Finding the median of n unsorted numbers can be done in…",["O(log n) expected","O(n) expected","only O(n log n)","O(n²) at best"],1,"You don't need a full sort.","Quickselect finds the k-th smallest in O(n) expected time."],
  ["code",2,"mc","Python: print({1: 'a', True: 'b'})",["{1: 'a', True: 'b'}","{1: 'b'}","{True: 'b'}","Error"],1,"True == 1 and they hash the same.","They are the same key; the first key object stays and the value is overwritten: {1: 'b'}."]
